/* Rentcam app interaction patches v7 — no document.write, scoped observer */
(function(){
  const BRAND_NAMES=['ARRI','SONY','Canon','RED','ZEISS','Cooke','Blackmagic Design','DJI','Aputure','Teradek','SmallHD','Sennheiser'];
  function navigate(path){if(typeof window.go==='function')window.go(path);else{history.pushState({},'',path);if(typeof window.render==='function')window.render();else location.href=path}}
  function handleBack(e){const btn=e.target?.closest?.('.product-detail-simple .back-link');if(!btn)return;e.preventDefault();e.stopPropagation();navigate('/produk')}
  function installStyle(){if(document.getElementById('rentcam-brand-marquee-style'))return;const st=document.createElement('style');st.id='rentcam-brand-marquee-style';st.textContent=`#app .brand-marquee-section{margin:34px 0 8px;padding:28px 0 12px;border-top:1px solid #ececec;overflow:hidden}#app .brand-marquee-title{margin:0 0 18px;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#8b8b8b}#app .brand-marquee-viewport{width:100%;overflow:hidden;position:relative;mask-image:linear-gradient(to right,transparent,#000 7%,#000 93%,transparent);-webkit-mask-image:linear-gradient(to right,transparent,#000 7%,#000 93%,transparent)}#app .brand-marquee-track{display:flex;align-items:center;width:max-content;gap:54px;animation:rentcamBrandScroll 28s linear infinite;will-change:transform}#app .brand-marquee-viewport:hover .brand-marquee-track{animation-play-state:paused}#app .brand-logo{height:58px;min-width:118px;padding:0 10px;display:flex;align-items:center;justify-content:center;white-space:nowrap;color:#111;font-size:20px;font-weight:900;letter-spacing:-.035em;opacity:.78;filter:grayscale(1)}@keyframes rentcamBrandScroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}@media(max-width:620px){#app .brand-marquee-track{gap:28px;animation-duration:22s}#app .brand-logo{height:46px;min-width:90px;font-size:16px}}@media(prefers-reduced-motion:reduce){#app .brand-marquee-track{animation:none}}`;document.head.appendChild(st)}
  function mount(){if(!location.pathname.startsWith('/produk/'))return;const related=document.getElementById('rentcam-related-products');if(!related)return;installStyle();let section=document.getElementById('rentcam-brand-marquee');if(!section){section=document.createElement('section');section.id='rentcam-brand-marquee';section.className='brand-marquee-section';const all=[...BRAND_NAMES,...BRAND_NAMES];section.innerHTML=`<div class="brand-marquee-title">Brand Equipment</div><div class="brand-marquee-viewport"><div class="brand-marquee-track">${all.map(n=>`<div class="brand-logo">${n}</div>`).join('')}</div></div>`}if(related.nextElementSibling!==section)related.insertAdjacentElement('afterend',section)}
  document.addEventListener('click',handleBack,true);document.addEventListener('touchend',handleBack,true);
  let queued=false;function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;mount()})}
  const app=document.getElementById('app');if(app)new MutationObserver(schedule).observe(app,{childList:true,subtree:true});addEventListener('popstate',schedule);schedule();
})();